import{_ as l,a0 as o,w as r,s as d,ao as p,I as n,a1 as a,A as e,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"用 Python 3.8 中的這個位置技巧讓你的 API 變得更好 | LCTT x X-CMD","titleTemplate":false,"description":"用 Python 3.8 中的這個位置技巧讓你的 API 變得更好 | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Python 3.8 中的這個位置技巧讓你的 API 變得更好 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Python 3.8 中的這個位置技巧讓你的 API 變得更好 | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20210520 Make your API better with this positional trick from Python 3.8","title":"用 Python 3.8 中的這個位置技巧讓你的 API 變得更好","tag":"202106","desc":""},"relativePath":"202106/20210520 Make your API better with this positional trick from Python 3.8.md","filePath":"[post].md"}'),h={name:"202106/20210520 Make your API better with this positional trick from Python 3.8.md"};function u(g,s,k,b,c,f){const t=o("Link");return r(),d("div",null,[s[19]||(s[19]=p('<h1 id="用-python-3-8-中的這個位置技巧讓你的-api-變得更好" tabindex="-1">用 Python 3.8 中的這個位置技巧讓你的 API 變得更好 <a class="header-anchor" href="#用-python-3-8-中的這個位置技巧讓你的-api-變得更好" aria-label="Permalink to “用 Python 3.8 中的這個位置技巧讓你的 API 變得更好”">​</a></h1><blockquote><p>探索只接受位置參數和其他兩個未被充分利用但仍然有用的 Python 特性。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202106/07/164929k51eccocxkx4xf11.jpg" alt=""></p><p>這是 Python 3.x 首發特性系列文章的第九篇。Python 3.8 於 2019 年首次發佈，兩年後，它的許多很酷的新特性仍然沒有被使用。下面是其中的三個。</p><h3 id="importlib-metadata" tabindex="-1">importlib.metadata <a class="header-anchor" href="#importlib-metadata" aria-label="Permalink to “importlib.metadata”">​</a></h3>',5)),n("p",null,[a(t,{href:"https://packaging.python.org/specifications/entry-points/"},{default:e(()=>[...s[0]||(s[0]=[i("入口點",-1)])]),_:1}),s[2]||(s[2]=i(" 在 Python 包中被用來做各種事情。大多數人熟悉的是 ",-1)),a(t,{href:"https://python-packaging.readthedocs.io/en/latest/command-line-scripts.html"},{default:e(()=>[...s[1]||(s[1]=[i("console_scripts",-1)])]),_:1}),s[3]||(s[3]=i(" 入口點，不過 Python 中的許多插件系統都使用它們。",-1))]),s[20]||(s[20]=p(`<p>在 Python 3.8 之前，從 Python 中讀取入口點的最好方法是使用 <code>pkg_resources</code>，這是一個有點笨重的模組，它是 <code>setuptools</code> 的一部分。</p><p>新的 <code>importlib.metadata</code> 是一個內置模組，它允許訪問同樣的東西：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from importlib import metadata as importlib_metadata</span></span>
<span class="line"><span></span></span>
<span class="line"><span>distribution = importlib_metadata.distribution(&quot;numpy&quot;)</span></span>
<span class="line"><span>distribution.entry_points</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    [EntryPoint(name=&#39;f2py&#39;, value=&#39;numpy.f2py.f2py2e:main&#39;, group=&#39;console_scripts&#39;),</span></span>
<span class="line"><span>     EntryPoint(name=&#39;f2py3&#39;, value=&#39;numpy.f2py.f2py2e:main&#39;, group=&#39;console_scripts&#39;),</span></span>
<span class="line"><span>     EntryPoint(name=&#39;f2py3.9&#39;, value=&#39;numpy.f2py.f2py2e:main&#39;, group=&#39;console_scripts&#39;)]</span></span></code></pre></div><p>入口點並不是 <code>importlib.metadata</code> 允許訪問的唯一東西。可以調試、報告，或者（在極端情況下）觸發兼容模式，你也可以在運行時檢查依賴的版本！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>f&quot;{distribution.metadata[&#39;name&#39;]}=={distribution.version}&quot;\`[/code] [code]\`    &#39;numpy==1.20.1&#39;</span></span></code></pre></div><h3 id="只接受位置參數" tabindex="-1">只接受位置參數 <a class="header-anchor" href="#只接受位置參數" aria-label="Permalink to “只接受位置參數”">​</a></h3><p>強制關鍵字的參數在傳達 API 作者的意圖方面取得巨大成功之後，另一個空白被填補了：只接受位置參數。</p><p>特別是對於那些允許使用任意關鍵字的函數（例如，生成數據結構），這意味着對允許的參數名稱的限制更少：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def some_func(prefix, /, **kwargs):</span></span>
<span class="line"><span>    print(prefix, kwargs)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>some_func(&quot;a_prefix&quot;, prefix=&quot;prefix keyword value&quot;)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>   a_prefix {&#39;prefix&#39;: &#39;prefix keyword value&#39;}\`</span></span></code></pre></div><p>注意，令人困惑的是，<em>變量</em> <code>prefix</code> 的值與 <code>kwargs[&quot;prefix&quot;]</code> 的值不同。就像在很多地方一樣，要注意小心使用這個功能。</p><h3 id="自我調試表達式" tabindex="-1">自我調試表達式 <a class="header-anchor" href="#自我調試表達式" aria-label="Permalink to “自我調試表達式”">​</a></h3><p>50 多年來，<code>print()</code> 語句（及其在其他語言中的對應語句）一直是快速調試輸出的最愛。</p><p>但是我們在打印語句方面取得了很大的進展，比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>special_number = 5</span></span>
<span class="line"><span>print(&quot;special_number = %s&quot; % special_number)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    special_number = 5</span></span></code></pre></div><p>然而，自我記錄的 f-strings 使它更容易明確：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>print(f&quot;{special_number=}&quot;)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    special_number=5\`</span></span></code></pre></div><p>在 f-string 插值部分的末尾添加一個 <code>=</code>，可以保留字面部分，同時添加數值。</p><p>當更復雜的表達式在該部分內時，這就更有用了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>values = {}</span></span>
<span class="line"><span>print(f&quot;{values.get(&#39;something&#39;, &#39;default&#39;)=}&quot;)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    values.get(&#39;something&#39;, &#39;default&#39;)=&#39;default&#39;</span></span></code></pre></div><h3 id="歡迎來到-2019-年" tabindex="-1">歡迎來到 2019 年 <a class="header-anchor" href="#歡迎來到-2019-年" aria-label="Permalink to “歡迎來到 2019 年”">​</a></h3><p>Python 3.8 大約在兩年前發佈，它的一些新特性非常酷，而且沒有得到充分利用。如果你還沒使用，那麼將他們添加到你的工具箱中。</p><hr>`,28)),n("p",null,[s[5]||(s[5]=i("via: ",-1)),a(t,{href:"https://opensource.com/article/21/5/python-38-features"},{default:e(()=>[...s[4]||(s[4]=[i("https://opensource.com/article/21/5/python-38-features",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=i("作者：",-1)),a(t,{href:"https://opensource.com/users/moshez"},{default:e(()=>[...s[6]||(s[6]=[i("Moshe Zadka",-1)])]),_:1}),s[11]||(s[11]=i(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[7]||(s[7]=[i("lujun9972",-1)])]),_:1}),s[12]||(s[12]=i(" 譯者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:e(()=>[...s[8]||(s[8]=[i("geekpi",-1)])]),_:1}),s[13]||(s[13]=i(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:e(()=>[...s[9]||(s[9]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[14]||(s[14]=[i("LCTT",-1)])]),_:1}),s[17]||(s[17]=i(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:e(()=>[...s[15]||(s[15]=[i("Linux中國",-1)])]),_:1}),s[18]||(s[18]=i(" 榮譽推出",-1))])])}const x=l(h,[["render",u]]);export{P as __pageData,x as default};
